      ('H2','同时导入'),
      ('Code',"// 全名和别名可以一起用\nimport { signal, s, computed, c } from 'xunay'\n\nconst a = signal(0)   // 全名\nconst b = s(0)        // 别名\n// a 和 b 都是 signal",'xuy'),
