      ('H2','返回值'),
      ('P','返回一个只读函数 c()。读它返回缓存值；依赖变化时下次读会重算。'),
      ('H2','示例'),
      ('Code',"const a = signal(1)\nconst b = signal(2)\nconst sum = computed(() => a() + b())\n\nsum()      // 3\na(10)\nsum()      // 12\nb(20)\nsum()      // 30",'xuy'),
      ('H2','特性'),
