      ('Code',"const price = signal(100)\nconst qty = signal(3)\nconst subtotal = computed(() => price() * qty())\nconst tax = computed(() => subtotal() * 0.13)\nconst total = computed(() => subtotal() + tax())\n\ntotal()   // 100*3 + 100*3*0.13 = 339",'xuy'),
