      ('Code',"// tokenizer.js\nconst TAGS = new Set('div span p a button input ...'.split(' '))\n\n// 加新标签\nTAGS.add('video')\nTAGS.add('canvas')\nTAGS.add('audio')",'js'),
      ('H2','加属性处理'),
