      ('P','xuyc 只做一件事：把 .xuy 编译成能在浏览器跑的代码。不需要 HMR、不需要插件——改完刷新页面就行。'),
      ('H2','npm 脚本集成'),
      ('Code',"{\n  \"scripts\": {\n    \"build\": \"node ../bin/xuyc.js build app.xuy --out dist\",\n    \"dev\": \"npm run build && cd dist && python3 -m http.server 8080\"\n  }\n}",'json'),
