      ('Code',"export type Signal<T> = {\n  (): T\n  (v: T | ((prev: T) => T)): T\n}\n\nexport type Accessor<T> = () => T\n\nexport interface VNode {\n  [ELEMENT]: true\n  type: string\n  props: Record<string, unknown>\n  children: unknown[]\n}",'ts'),
