      ('Code',"test('按钮点击 +1', () => {\n  const n = signal(0)\n  const btn = button({ on: { click: () => n(v => v + 1) } })\n  document.body.appendChild(render(btn))\n  btn.click()\n  assert.equal(n(), 1)\n})",'js'),
